def first_repeated_value(nums):
    seen = set()
    for value in nums:
        if value in seen:
            return value
        seen.add(value)
    return -1

solution.javascript:
export function firstRepeatedValue(nums) {
  const seen = new Set();
  for (const value of nums) {
    if (seen.has(value)) return value;
    seen.add(value);
  }
  return -1;
}
